#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
uniform float amzp_scalex;
uniform float2 amzp_positionn;
uniform float amzp_progressa;
uniform float amzp_scalen;
uniform float amzp_anglen;
uniform float amzp_alphan;
uniform float2 amzp_position;
uniform float2 amzp_sstretch;
uniform float2 amzp_stretch;
uniform float amzp_progressb;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float amzp_visible;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
layout(color) uniform half4 amzp_color2;
uniform float amzp_alpha;
uniform float amzp_bright;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
          float sun(float2 uv, float battery)
        {
          float val = smoothstep(0.3, 0.29, length(uv));
          float bloom = smoothstep(0.7, 0.0, length(uv));
            float cut = 3.0 * sin((uv.y + amzp_progressa * 0.2 * (battery + 0.02)) * 100.0)
            + clamp(uv.y * 14.0 + 1.0, -6.0, 6.0);
            cut = clamp(cut, 0.0, 1.0);
            return clamp(val * cut, 0.0, 1.0) + bloom * 0.6;
        }
        float grid(float2 uv, float battery)
        {
            float2 amzLocal_size = float2(uv.y, uv.y * uv.y * 0.2) * 0.01;
            uv += float2(0.0, amzp_progressb * 4.0 * (battery + 0.05));
            uv = abs(fract(uv) - 0.5);
          float2 lines = smoothstep(amzLocal_size, float2(0.0), uv);
          lines += smoothstep(amzLocal_size * 5.0, float2(0.0), uv) * 0.4 * battery;
            return clamp(lines.x + lines.y, 0.0, 3.0);
        }
        void amzRender() {
        float2 sscaleVec;
        sscaleVec = float2(1.0*amzp_sstretch.x,1.0*amzp_sstretch.y);
        float4 texColor = amzTexture(0, (amzScreenNorm()/sscaleVec));
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        if ((amzp_visible>0.5)) { satriyaid /= 100.0; }
        else { satriyaid /= (amzp_scalex>0.5)? (amzp_scale+3.5) : amzp_scale; }
        satriyaid *= rot2m((180.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 sunst;
        sunst = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        sunst.y*=layer.y/layer.x;
        sunst /= (amzp_scalex>0.5)? (amzp_scalen+3.5) : amzp_scalen;
        sunst *= rot2m((180.0+amzp_anglen)*0.0174533);
        sunst += float2((375.0+amzp_positionn.x), (-180.0+amzp_positionn.y))*float2(-1.,1.)/500.;
     float4 fragColor;
          float2 scaleVec;
            scaleVec = float2(1.0*amzp_stretch.x,1.0*amzp_stretch.y);
            float2 uv = satriyaid/scaleVec;
            float battery = 1.0;
            {
                float fog = smoothstep(0.1, -0.02, abs(uv.y + 0.2));
                float3 col = float3(0.0, 0.1, 0.2);
                if (uv.y < -0.2)
                {
                    uv.y = 3.0 / (abs(uv.y + 0.2) + 0.05);
                    uv.x *= uv.y * 1.0;
                    float gridVal = grid(uv, battery);
                    col = mix(col, float3(amzp_color4.rgb), gridVal);
                }
                else
                {
                    float2 sunUV = sunst;
                    sunUV += float2(0.75, 0.2);
                    col = float3(amzp_color1.rgb);
                    float sunVal = sun(sunUV, battery);
                    col = mix(col, float3(float3(amzp_color3.rgb)), sunUV.y * 2.0 + 0.2);
                    col = mix(float3(0.0, 0.0, 0.0), col, (sunVal*amzp_alphan));
                    col += mix( col, mix(float3(amzp_color4.rgb), float3(0.0, 0.0, 0.2), clamp(uv.y * 3.5 + 3.0, 0.0, 1.0)), float3(1.0, 1.0, 1.0) );
                    col = mix(col, float3(0.0, 0.0, 0.2), 1.0 - smoothstep(0.075 - 0.0001, 0.075, float3(1.0, 1.0, 1.0)));
                }
                col += fog * fog * fog;
                col = mix(float3(amzp_color2.rgb), col, battery * 0.7);
                fragColor = float4(col,1.0);
            }
             float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
